typedef int EventType;

class ScoringManager {
  char padding[0x20];
  int score;
public:
  void SetScore(const int s) { score = s; }
  int GetScore(void) const { return score; }
};

class kellyslater_controller {
public:
  ScoringManager my_scoreManager;
};

class world_dynamics_system {
  kellyslater_controller *ks_controller[2];
public:
  kellyslater_controller *get_ks_controller(int n) { return ks_controller[n]; }
};

extern world_dynamics_system *g_world_ptr;

class SoundScriptManager {
public:
  static SoundScriptManager *inst();
  int playEvent(EventType type, void *entity = 0, float fadeInTime = 0);
};

const EventType SS_ICON_FAILED_TRICKCHAIN = 0;
const int ICON_STATE_FROZEN = 3;

class IGOIconManager {
public:
  class Icon {
    char padding0[0x6c];
  public:
    float vy;
    char padding1[0x9];
    unsigned char state;
    char padding2[0x2];
  };

private:
  char padding0[0x700];
  Icon effectIcons[5];
  unsigned char numEffectIcons;
  unsigned char effectType;
  float effectTime;
  char padding1[0x420];
  Icon *icons;
  char padding2[0xc];
  int numIcons;
  int iconCounter;
  char padding3[0x4];
  int completedIcons;
  char padding4[0x5c];
  bool failure;
  int prepareFailure;
  char padding5[0x8];
  int trickStack[4];
  int tsSize;
  char padding6[0x105c];
  int scoreBonuses[5];

public:
  void TrickChain(int trickIdx);
  void PopCompletedIcons(bool success);
};

void IGOIconManager::PopCompletedIcons(bool success)
{
  if(prepareFailure)
    return;

  if (completedIcons == 0)
    return;

  failure = false;

  if(success)
  {
    iconCounter += completedIcons;
    int score = g_world_ptr->get_ks_controller(0)->my_scoreManager.GetScore();
    score += scoreBonuses[completedIcons-1];
    g_world_ptr->get_ks_controller(0)->my_scoreManager.SetScore(score);

    numEffectIcons = 0;
    completedIcons = 0;
    for(int i=0; i<numIcons; i++)
      if(icons[i].vy == 0.0f)
        icons[i].vy = 0.01f;
  }
  else
  {
    SoundScriptManager::inst()->playEvent(SS_ICON_FAILED_TRICKCHAIN);
    effectType = 2;
    for(int i=0; i<numEffectIcons; i++)
      effectIcons[i].state = ICON_STATE_FROZEN;
    effectTime = 2.0f;
  }

  for(int i=0; i<tsSize; i++)
    TrickChain(trickStack[i]);
  tsSize = 0;
}
